export function LanguageLogo({ lang, size = 14 }: { lang: LogoLang; size?: number }) {
  switch (lang) {
    case 'python':
      return <PythonLogo size={size} />;
    case 'java':
      return <JavaLogo size={size} />;
    case 'csp':
      return <CspLogo size={size} />;
    case 'javascript':
      return <JavaScriptLogo size={size} />;
    case 'praxis':
      return <PraxisLogo size={size} />;
    case 'blocks':
      return <BlocksLogo size={size} />;
    default:
      return null;
  }
}
